const PRODUCTS = {
  notebook: {
    sku: "notebook",
    label: "Notebook",
    priceCents: 1200,
  },
  pen: {
    sku: "pen",
    label: "Pen",
    priceCents: 250,
  },
  planner: {
    sku: "planner",
    label: "Planner",
    priceCents: 2800,
  },
};

const SERVICES = {
  "gift-wrap": {
    sku: "svc-gift-wrap",
    label: "Gift wrap",
    priceCents: 499,
  },
};

export function getProduct(sku) {
  const product = PRODUCTS[sku];
  if (product === undefined) {
    throw new Error(`Unknown product sku: ${sku}`);
  }
  return product;
}

export function getService(serviceId) {
  return SERVICES[serviceId] ?? null;
}

export function listCatalogSkus() {
  return Object.keys(PRODUCTS).sort();
}

import { getProduct, getService } from "./catalog.mjs";

function itemSubtotalCents(item) {
  const product = getProduct(item.sku);
  return product.priceCents * item.quantity;
}

function notebookQuantity(items) {
  return items
    .filter((item) => item.sku === "notebook")
    .reduce((sum, item) => sum + item.quantity, 0);
}

function giftWrapLine(cart) {
  if (cart.giftWrap !== true) return null;
  const service = getService("gift-wrap");
  if (service === null) {
    throw new Error("Gift-wrap service is missing from the catalog");
  }
  return {
    sku: service.sku,
    label: service.label,
    priceCents: service.priceCents,
    message: cart.giftMessage ?? null,
  };
}

export function priceCart(cart) {
  const items = cart.items.map((item) => {
    const product = getProduct(item.sku);
    return {
      sku: product.sku,
      label: product.label,
      quantity: item.quantity,
      unitPriceCents: product.priceCents,
      subtotalCents: itemSubtotalCents(item),
    };
  });
  const merchandiseCents = items.reduce(
    (sum, item) => sum + item.subtotalCents,
    0,
  );
  const discountCents = notebookQuantity(items) >= 3 ? 300 : 0;
  const giftWrap = giftWrapLine(cart);
  const serviceLines = giftWrap === null ? [] : [giftWrap];
  const serviceCents = serviceLines.reduce(
    (sum, service) => sum + service.priceCents,
    0,
  );
  const shippingCents = merchandiseCents >= 4000 ? 0 : 599;
  const totalCents =
    merchandiseCents - discountCents + serviceCents + shippingCents;

  return {
    items,
    serviceLines,
    giftWrap: {
      requested: cart.giftWrap === true,
      applied: giftWrap !== null,
      message: cart.giftMessage ?? null,
    },
    totals: {
      merchandiseCents,
      discountCents,
      serviceCents,
      shippingCents,
      totalCents,
    },
  };
}

export function formatMoney(cents) {
  return `$${(cents / 100).toFixed(2)}`;
}

export function renderReceipt(pricedCart) {
  const lines = pricedCart.items.map(
    (item) =>
      `${item.quantity} x ${item.label}: ${formatMoney(item.subtotalCents)}`,
  );
  if (pricedCart.totals.discountCents > 0) {
    lines.push(`Bulk discount: -${formatMoney(pricedCart.totals.discountCents)}`);
  }
  for (const service of pricedCart.serviceLines) {
    lines.push(`${service.label}: ${formatMoney(service.priceCents)}`);
    if (service.message !== null && service.message !== "") {
      lines.push(`Gift message: ${service.message}`);
    }
  }
  lines.push(
    pricedCart.totals.shippingCents === 0
      ? "Shipping: FREE"
      : `Shipping: ${formatMoney(pricedCart.totals.shippingCents)}`,
  );
  lines.push(`Total: ${formatMoney(pricedCart.totals.totalCents)}`);
  return lines.join("\n");
}
